<?php
$lock = __DIR__ . '/install.lock'; $lockAlt = __DIR__ . '/LOCK';
if (file_exists($lock) || file_exists($lockAlt)) { header('Location: ../adm.php'); exit; }
function h($s){ return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }
$err=''; $ok='';
function adena_sql_statements(string $sql): array {
  $sql=preg_replace('/^\xEF\xBB\xBF/','',$sql); $out=[]; $buf=''; $q=null; $esc=false; $lc=false; $bc=false; $n=strlen($sql);
  for($i=0;$i<$n;$i++){ $ch=$sql[$i]; $nx=$i+1<$n?$sql[$i+1]:'';
    if($lc){ if($ch==="\n")$lc=false; continue; } if($bc){ if($ch==='*'&&$nx==='/'){$bc=false;$i++;} continue; }
    if($q!==null){ $buf.=$ch; if($esc)$esc=false; elseif($ch==='\\')$esc=true; elseif($ch===$q)$q=null; continue; }
    if($ch==='-'&&$nx==='-'){$lc=true;$i++;continue;} if($ch==='/'&&$nx==='*'){$bc=true;$i++;continue;} if($ch==='#'){$lc=true;continue;}
    if($ch==="'"||$ch==='"'||$ch==='`'){$q=$ch;$buf.=$ch;continue;} if($ch===';'){ $st=trim($buf); $buf=''; if($st!==''&&stripos($st,'DELIMITER')!==0)$out[]=$st; continue; } $buf.=$ch;
  } $st=trim($buf); if($st!=='')$out[]=$st; return $out;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
  $app_name=trim($_POST['app_name']??'Adena POS Belitung'); $branch_name=trim($_POST['branch_name']??'Belitung'); $branch_code=strtoupper(trim($_POST['branch_code']??'BLT'));
  $base_url=rtrim(trim($_POST['base_url']??''),'/'); $db_host=trim($_POST['db_host']??'127.0.0.1'); $db_port=trim($_POST['db_port']??'3306'); $db_name=trim($_POST['db_name']??''); $db_user=trim($_POST['db_user']??'root'); $db_pass=(string)($_POST['db_pass']??'');
  $admin_username=trim($_POST['admin_username']??'admin'); $admin_name=trim($_POST['admin_name']??'Administrator'); $admin_pass1=(string)($_POST['admin_pass1']??''); $admin_pass2=(string)($_POST['admin_pass2']??'');
  try{ if($app_name===''||$branch_name===''||$branch_code===''||$base_url===''||$db_name==='') throw new Exception('Nama aplikasi, cabang, kode cabang, Base URL, dan database wajib diisi.'); if($admin_pass1===''||$admin_pass1!==$admin_pass2) throw new Exception('Password admin tidak cocok.');
    $dump=__DIR__.'/../db/adena_latest_single_belitung.sql'; if(!is_file($dump)) throw new Exception('File database terbaru tidak ditemukan: /db/adena_latest_single_belitung.sql');
    $pdo=new PDO("mysql:host={$db_host};port={$db_port};charset=utf8mb4",$db_user,$db_pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
    $safeDb=str_replace('`','``',$db_name); $pdo->exec("CREATE DATABASE IF NOT EXISTS `{$safeDb}` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci"); $pdo->exec("USE `{$safeDb}`");
    foreach(adena_sql_statements(file_get_contents($dump)) as $stmt){ $pdo->exec($stmt); }
    $pdo->prepare("INSERT INTO branches (id,branch_code,branch_name,unit_type,is_kitchen,is_active,sort_order) VALUES (1,?,?, 'branch',0,1,0) ON DUPLICATE KEY UPDATE branch_code=VALUES(branch_code), branch_name=VALUES(branch_name), unit_type='branch', is_kitchen=0, is_active=1")->execute([$branch_code,$branch_name]);
    $pdo->exec("UPDATE branches SET is_active=0 WHERE id<>1"); try{$pdo->exec("UPDATE api_tokens SET branch_id=1 WHERE branch_id IS NULL OR branch_id<>1");}catch(Throwable $e){}
    $pdo->prepare("INSERT INTO users (username,name,role,password_hash) VALUES (?,?, 'owner', ?) ON DUPLICATE KEY UPDATE name=VALUES(name), role='owner', password_hash=VALUES(password_hash)")->execute([$admin_username,$admin_name,password_hash($admin_pass1,PASSWORD_DEFAULT)]);
    $set=$pdo->prepare("INSERT INTO settings (`key`,`value`) VALUES (?,?) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`)"); foreach(['active_branch_id'=>'1','branch_mode'=>'single','branch_name'=>$branch_name,'branch_code'=>$branch_code,'store_name'=>$app_name,'store_subtitle'=>'Makanan Khas Belitung','api_topology'=>'branch_to_branch,branch_to_kitchen,branch_to_backoffice,kitchen_to_backoffice'] as $k=>$v){$set->execute([$k,$v]);}
    $config=['app'=>['name'=>$app_name,'base_url'=>$base_url,'branch_name'=>$branch_name,'branch_code'=>$branch_code,'branch_mode'=>'single'],'db'=>['host'=>$db_host,'port'=>$db_port,'name'=>$db_name,'user'=>$db_user,'pass'=>$db_pass,'charset'=>'utf8mb4'],'security'=>['session_name'=>'ADENAPOSSESS']]; file_put_contents(__DIR__.'/../config.php',"<?php\nreturn ".var_export($config,true).";\n"); @mkdir(__DIR__.'/../private_uploads',0755,true); @mkdir(__DIR__.'/../uploads',0755,true); file_put_contents($lock,'installed '.date('c')); $ok="Instalasi selesai. Sistem aktif sebagai single cabang {$branch_name} ({$branch_code}).";
  }catch(Throwable $e){$err=$e->getMessage();}
}
