db_port" value="3306"></div><div><label>DB Name</label><input name="db_name"></div><div><label>DB User</label><input name="db_user" value="root"></div><div class="full"><label>DB Password</label><input name="db_pass" type="password"></div><div><label>Admin Username</label><input name="admin_username" value="admin"></div><div><label>Admin Name</label><input name="admin_name" value="Administrator"></div><div><label>Password Admin</label><input name="admin_pass1" type="password"></div><div><label>Ulangi Password</label><input name="admin_pass2" type="password"></div><div class="full"><button class="btn" type="submit">Install Database Terbaru</button></div></div></form></div></body></html>
